// Extrai o texto da mensagem e o número do remetente.
// Ignora mensagens enviadas pelo próprio bot (fromMe: true).
// n8n webhook typeVersion 2 envolve o payload em .body
const raw = $input.item.json;
const body = raw.body !== undefined ? raw.body : raw;

// Ignora mensagens do próprio bot para evitar loop
if (body.data?.key?.fromMe === true) {
  return [];
}

let message = null;
let remoteJid = null;

// 1. Formato genérico: { "message": "..." }
if (typeof body.message === 'string' && body.message.trim()) {
  message = body.message.trim();
}
// 2. WAHA (WhatsApp HTTP API)
else if (body.payload?.body) {
  message = String(body.payload.body).trim();
}
// 3. Evolution API v2
else if (body.data?.message?.conversation) {
  message = String(body.data.message.conversation).trim();
} else if (body.data?.message?.extendedTextMessage?.text) {
  message = String(body.data.message.extendedTextMessage.text).trim();
}
// 4. WhatsApp Cloud API (Meta / 360dialog)
else if (body.entry?.[0]?.changes?.[0]?.value?.messages?.[0]?.text?.body) {
  message = String(body.entry[0].changes[0].value.messages[0].text.body).trim();
}
// 5. Campo "text" genérico
else if (typeof body.text === 'string' && body.text.trim()) {
  message = body.text.trim();
}

// ── Extrai número do remetente (sem sufixo @s.whatsapp.net) ───────────────
let rawJid = null;

if (body.data?.key?.remoteJid) {
  rawJid = body.data.key.remoteJid;
} else if (body.payload?.from) {
  rawJid = body.payload.from;
} else if (body.entry?.[0]?.changes?.[0]?.value?.messages?.[0]?.from) {
  rawJid = body.entry[0].changes[0].value.messages[0].from;
} else if (body.from || body.phone || body.number) {
  rawJid = body.from || body.phone || body.number;
}

// Remove @s.whatsapp.net, @c.us e similares
if (rawJid) {
  remoteJid = rawJid.replace(/@[^@]+$/, '');
}

return [{ json: { message, remoteJid } }];

const message = $input.item.json.message;

if (!message || typeof message !== 'string') {
  return [{ json: { success: false, originalMessage: null } }];
}

const text = message.trim();

// ── Extrai valor monetário ─────────────────────────────────────────────────
// Aceita: R$ 35 | R$35 | R$ 35,90 | R$ 35.90 | 25,90 | 12
const valueRegex = /(?:r\$\s*)?(\d{1,6}(?:[.,]\d{1,2})?)/i;
const match = text.match(valueRegex);

if (!match) {
  return [{ json: { success: false, originalMessage: text } }];
}

const amount = parseFloat(match[1].replace(',', '.'));

if (isNaN(amount) || amount <= 0) {
  return [{ json: { success: false, originalMessage: text } }];
}

// ── Extrai descrição ────────────────────────────────────────────────────────
const descPatterns = [
  /(?:gastei|paguei|gasto|pago|comprei|compra)(?:\s+r\$\s*|\s+)\d+(?:[.,]\d{1,2})?\s+(?:no|na|de|em|do|da|num|numa|com)\s+(.+)/i,
  /(?:no|na|de|em|do|da|num|numa|com)\s+(.+)$/i,
];

let description = null;
for (const pattern of descPatterns) {
  const m = text.match(pattern);
  if (m) { description = m[1].trim(); break; }
}

if (!description) {
  description = text
    .replace(/^(?:gastei|paguei|gasto|pago|comprei|compra)\s+/i, '')
    .replace(/(?:r\$\s*)?\d+(?:[.,]\d{1,2})?\s*/i, '')
    .trim();
}

if (!description) {
  return [{ json: { success: false, originalMessage: text } }];
}

// Capitaliza primeira letra
description = description.charAt(0).toUpperCase() + description.slice(1).toLowerCase();

// ── Categorização por palavras-chave ────────────────────────────────────────
const lower = description.toLowerCase();
let category = 'Outros';

if (/almo[cç]|jantar|lanche|caf[eé]|restaurante|comida|pizza|hambur|sushi|refei[cç]|ifood|rappi|delivery/.test(lower)) {
  category = 'Alimentação';
} else if (/mercado|supermercado|hortifruti|feira|atacad/.test(lower)) {
  category = 'Mercado';
} else if (/combust[ií]vel|gasolina|posto|etanol|diesel|uber|99|taxi|t[aá]xi|metr[oô]|[oô]nibus|passagem|estacion|pedag/.test(lower)) {
  category = 'Transporte';
} else if (/rem[eé]dio|farm[aá]cia|m[eé]dico|consulta|exame|hospital|cl[ií]nica|sa[uú]de|plano|dental/.test(lower)) {
  category = 'Saúde';
}

// ── Data no fuso horário America/Recife ─────────────────────────────────────
const now = new Date();
const parts = new Intl.DateTimeFormat('pt-BR', {
  timeZone: 'America/Recife',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).formatToParts(now).reduce((acc, p) => ({ ...acc, [p.type]: p.value }), {});
const date = `${parts.year}-${parts.month}-${parts.day}`;

// Formata valor para exibição (ex: 35,00)
const amountFormatted = amount.toFixed(2).replace('.', ',');

return [{
  json: {
    success: true,
    amountFormatted,
    description,
    category,
    payload: {
      type: 'despesa',
      description,
      amount,
      date,
      category,
      note: `Registrado pelo WhatsApp: ${text}`,
      paid: true,
    },
    originalMessage: text,
  }
}];
